#!/usr/bin/env node
// Deterministic CommonJS bundle for PDG's basename-only embedded module loader.
// Upstream sources remain unchanged. Optional native accelerators are excluded.
'use strict';
const fs = require('fs');
const path = require('path');
const root = path.resolve(__dirname, '..');
const dir = path.join(root, 'src/js/vendor/ws');
const names = ['index.js', ...fs.readdirSync(path.join(dir, 'lib')).filter(n => n.endsWith('.js')).sort().map(n => 'lib/' + n)];
let result = '// Generated by tools/bundle-websocket.js from ws 8.22.0. Do not edit.\n/*\n' + fs.readFileSync(path.join(dir, 'LICENSE'), 'utf8') + '\n*/\n';
result += '(function(outerRequire) {\nvar factories = {\n';
result += names.map(name => JSON.stringify(name) + ': function(require, module, exports) {\n' + fs.readFileSync(path.join(dir, name), 'utf8') + '\n}').join(',\n');
result += `\n};
var cache = {};
function load(name) {
    if (cache[name]) return cache[name].exports;
    var mod = cache[name] = {exports:{}};
    factories[name](function(request) {
        if (request === 'bufferutil' || request === 'utf-8-validate') throw new Error('Optional accelerator excluded');
        if (request[0] !== '.') return outerRequire(request);
        var parts = name.split('/'); parts.pop();
        request.split('/').forEach(function(part) {
            if (part === '..') parts.pop(); else if (part !== '.') parts.push(part);
        });
        return load(parts.join('/') + (request.endsWith('.js') ? '' : '.js'));
    }, mod, mod.exports);
    return mod.exports;
}
var ws = load('index.js');
exports.WebSocket = ws;
exports.WebSocketServer = ws.WebSocketServer;
})(require);
`;
const output = path.join(root, 'src/js/net_ws_bundle.js');
if (process.argv.includes('--check')) {
    if (fs.readFileSync(output, 'utf8') !== result) throw Error('WebSocket bundle needs regeneration');
} else fs.writeFileSync(output, result);
